@@ -1,1 +1,91 @@
+syntax = "proto3";

+package tensorflow.serving;
+
+option java_multiple_files = true;
+option java_package = "com.example.objectdetector.grpc";
+option java_outer_classname = "PredictionServiceProto";
+
+// Request message for prediction
+message PredictRequest {
+ // Model specification
+ ModelSpec model_spec = 1;
+ 
+ // Input tensors
+ map<string, TensorProto> inputs = 2;
+}
+
+// Response message for prediction
+message PredictResponse {
+ // Output tensors
+ map<string, TensorProto> outputs = 1;
+}
+
+// Model specification
+message ModelSpec {
+ // Required servable name
+ string name = 1;
+ 
+ // Optional model signature to use
+ string signature_name = 2;
+ 
+ // Optional model version
+ int64 version = 3;
+}
+
+// Tensor representation
+message TensorProto {
+ // Data type of tensor elements
+ DataType dtype = 1;
+ 
+ // Shape of the tensor
+ TensorShapeProto tensor_shape = 2;
+ 
+ // Tensor content
+ repeated float float_val = 5;
+ repeated int32 int_val = 7;
+ repeated int64 int64_val = 9;
+}
+
+// Tensor shape representation
+message TensorShapeProto {
+ repeated Dim dim = 2;
+ 
+ message Dim {
+ int64 size = 1;
+ }
+}
+
+// Data types
+enum DataType {
+ DT_INVALID = 0;
+ DT_FLOAT = 1;
+ DT_DOUBLE = 2;
+ DT_INT32 = 3;
+ DT_UINT8 = 4;
+ DT_INT16 = 5;
+ DT_INT8 = 6;
+ DT_STRING = 7;
+ DT_COMPLEX64 = 8;
+ DT_INT64 = 9;
+ DT_BOOL = 10;
+ DT_QINT8 = 11;
+ DT_QUINT8 = 12;
+ DT_QINT32 = 13;
+ DT_BFLOAT16 = 14;
+ DT_QINT16 = 15;
+ DT_QUINT16 = 16;
+ DT_UINT16 = 17;
+ DT_COMPLEX128 = 18;
+ DT_HALF = 19;
+ DT_RESOURCE = 20;
+ DT_VARIANT = 21;
+ DT_UINT32 = 22;
+ DT_UINT64 = 23;
+}
+
+// Prediction service
+service PredictionService {
+ // Predict using the specified model
+ rpc Predict(PredictRequest) returns (PredictResponse);
+}
