n // Create input tensor\n val inputTensor = TensorProto.newBuilder()\n .setDtype(DataType.DT_FLOAT)\n .setTensorShape(tensorShape)\n .addAllFloatVal(flatData)\n .build()\n\n // Create model spec\n val modelSpec = ModelSpec.newBuilder()\n .setName(\"mobilenet_ssd\")\n .setSignatureName(\"serving_default\")\n .build()\n\n // Build request\n return PredictRequest.newBuilder()\n .setModelSpec(modelSpec)\n .putInputs(\"input_tensor\", inputTensor)\n .build()\n }\n\n private fun parseGrpcResponse(response: PredictResponse): GrpcPredictionResponse {\n val outputs = response.outputsMap\n\n val numDetections = outputs[\"num_detections\"]?.floatValList?.get(0) ?: 0f\n val detectionBoxes = outputs[\"detection_boxes\"]?.floatValList?.chunked(4) ?: emptyList()\n val detectionClasses = outputs[\"detection_classes\"]?.floatValList ?: emptyList()\n val detectionScores = outputs[\"detection_scores\"]?.floatValList ?: emptyList()\n\n return GrpcPredictionResponse(\n predictions = listOf(\n GrpcPrediction(\n numDetections = numDetections,\n detectionBoxes = detectionBoxes.map { it.toList() },\n detectionClasses = detectionClasses.toList(),\n detectionScores = detectionScores.toList()\n )\n )\n )\n }\n\n fun shutdown() {\n if (!channel.isShutdown) {\n channel.shutdown()\n }\n }\n}\n\n// gRPC specific data classes\ndata class GrpcPredictionResponse(\n val predictions: List<GrpcPrediction>\n)\n\ndata class GrpcPrediction(\n val numDetections: Float,\n val detectionBoxes: List<List<Float>>,\n val detectionClasses: List<Float>,\n val detectionScores: List<Float>\n)\n\nclass GrpcPredictionException(message: String, cause: Throwable? = null) : Exception(message, cause)\n\nobject grpcApi {\n val service: GrpcApiService by lazy {\n GrpcApiService()\n }\n}", "instructions": "I will create a gRPC service implementation that interfaces with the TensorFlow Serving gRPC endpoint.", "target_file": "app/src/main/java/com/example/objectdetector/network/GrpcApiService.kt"}"}}]},{"role":"tool","name":"