Body = response.body?.string() \n ?: throw GrpcPredictionException(\"Empty response body\")\n\n val grpcResponse = json.decodeFromString(GrpcPredictResponse.serializer(), responseBody)\n \n // Convert to our standard format\n GrpcPredictionResponse(\n predictions = grpcResponse.predictions.map { prediction ->\n GrpcPrediction(\n numDetections = prediction.num_detections,\n detectionBoxes = prediction.detection_boxes,\n detectionClasses = prediction.detection_classes,\n detectionScores = prediction.detection_scores\n )\n }\n )\n \n } catch (e: Exception) {\n throw GrpcPredictionException(\"gRPC prediction failed: ${e.message}\", e)\n }\n }\n }\n\n fun shutdown() {\n // OkHttp client cleanup is automatic\n }\n}\n\n// Request/Response data classes for gRPC HTTP API\n@Serializable\ndata class GrpcPredictRequest(\n val instances: List<List<List<List<Int>>>>\n)\n\n@Serializable\ndata class GrpcPredictResponse(\n val predictions: List<GrpcPredictPrediction>\n)\n\n@Serializable\ndata class GrpcPredictPrediction(\n val num_detections: Float,\n val detection_classes: List<Float>,\n val detection_scores: List<Float>,\n val detection_boxes: List<List<Float>>\n)\n\n// gRPC specific data classes for UI compatibility\ndata class GrpcPredictionResponse(\n val predictions: List<GrpcPrediction>\n)\n\ndata class GrpcPrediction(\n val numDetections: Float,\n val detectionBoxes: List<List<Float>>,\n val detectionClasses: List<Float>,\n val detectionScores: List<Float>\n)\n\nclass GrpcPredictionException(message: String, cause: Throwable? = null) : Exception(message, cause)\n\nobject grpcApi {\n val service: GrpcApiService by lazy {\n GrpcApiService()\n }\n}", "instructions": "I will implement a working gRPC service using HTTP/JSON communication instead of complex protobuf, making it much simpler and more reliable.", "target_file": "app/src/main/java/com/example/objectdetector/network/GrpcApiService.kt"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"tooluse_ogsdQWiESfmVK5bZ255l5