# we already have the repos; if not, clone with --depth 1
# git clone --depth 1 https://github.com/tensorflow/serving.git
# git clone --depth 1 https://github.com/tensorflow/tensorflow.git

cd C:\Users\Mohammed\AndroidStudioProjects\ObjectDetector

# 1-A · wipe proto folder to start clean
Remove-Item -Recurse -Force app\src\main\proto
mkdir app\src\main\proto

# 1-B · copy ALL TensorFlow-Serving API protos, preserving directory layout
Copy-Item "$Env:USERPROFILE\Desktop\serving\tensorflow_serving" `
 "app\src\main\proto\tensorflow_serving" -Recurse

# 1-C · copy the WHOLE TensorFlow framework tree that contains every proto
Copy-Item "$Env:USERPROFILE\Desktop\tensorflow\tensorflow\core" `
 "app\src\main\proto\tensorflow\core" -Recurse
Copy-Item "$Env:USERPROFILE\Desktop\tensorflow\tsl" `
 "app\src\main\proto\tsl" -Recurse
Copy-Item "$Env:USERPROFILE\Desktop\tensorflow\xla" `
 "app\src\main\proto\xla" -Recurse
```

That guarantees every import path mentioned anywhere under `tensorflow_serving/apis` is resolvable.

--------------------------------------------------------------------------------
