suspend fun predict(pixelData: Array<Array<Array<Int>>>): PredictResponse {
 val tensor = buildTensor(pixelData) // make TensorProto
 val request = PredictRequest.newBuilder()
 .setModelSpec(
 ModelSpec.newBuilder()
 .setName("mobilenet_ssd")
 .setSignatureName("serving_default")
 )
 .putInputs("input_tensor", tensor)
 .build()

 return stub.predict(request)
}
```

--------------------------------------------------------------------------------
