@Composable
fun FullScreenImageDialog(
 bitmap: Bitmap,
 onDismiss: () -> Unit
) {
 var scale by remember { mutableFloatStateOf(1f) }
 var rotation by remember { mutableFloatStateOf(0f) }
 var offset by remember { mutableStateOf(Offset.Zero) }

 val state = rememberTransformableState { zoomChange, offsetChange, rotationChange ->
 scale *= zoomChange
 rotation += rotationChange
 offset += offsetChange
 }

 Dialog(
 onDismissRequest = onDismiss,
 properties = DialogProperties(
 dismissOnBackPress = true,
 dismissOnClickOutside = true,
 usePlatformDefaultWidth = false
 )
 ) {
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.9f))
 .clickable { onDismiss() }
 ) {
 // Full-screen image with zoom/pan support
 AsyncImage(
 model = bitmap,
 contentDescription = stringResource(R.string.selected_image),
 contentScale = ContentScale.Fit,
 modifier = Modifier
 .fillMaxSize()
 .graphicsLayer(
 scaleX = scale,
 scaleY = scale,
 rotationZ = rotation,
 translationX = offset.x,
 translationY = offset.y
 )
 .transformable(state = state)
 .clickable(enabled = false) { } // Prevent dismiss when touching image
 )

 // Close button
 CustomIconButton(
 onClick = onDismiss,
 icon = Icons.Filled.CloseFullscreen,
 iconDescription = stringResource(R.string.exit_full_screen),
 modifier = Modifier.align(Alignment.BottomStart)
 )
 // TODO add a download button to save the annotated image to the user's gallery
 }
 }
}
